python3 - <<'EOF'
import sys
sys.path.insert(0, "src")
from verify import decode_png, px
img = decode_png("render-crop.png")
w, h, _, _ = img
def lum(p): return sum(p[:3]) / 3
S = 1.25

# per-row bright counts
rows = [sum(1 for x in range(0, w, 3) if lum(px(img, x, y)) > 140) for y in range(h)]
bands = []
inband = False
for y, n in enumerate(rows):
    if n > 20 and not inband:
        start = y; inband = True
    if n <= 20 and inband:
        if y - start > 5:
            bands.append((start, y))
        inband = False
for (start, end) in bands:
    # density per x column within band
    cols = {}
    for y in range(start, end, 2):
        for x in range(0, w, 3):
            if lum(px(img, x, y)) > 140:
                cols[x] = cols.get(x, 0) + 1
    dense = [x for x, c in cols.items() if c >= 2]
    if dense:
        print(f"band y {start:4d}-{end:4d} (orig {start/S:5.0f}-{end/S:5.0f})  x {min(dense):4d}-{max(dense):4d} (orig {min(dense)/S:4.0f}-{max(dense)/S:4.0f})")
EOF
